CREATE TABLE carriers(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, code VARCHAR(80) NOT NULL UNIQUE, name VARCHAR(200) NOT NULL, phone VARCHAR(100) NOT NULL DEFAULT '', address VARCHAR(500) NOT NULL DEFAULT '', province VARCHAR(200) NOT NULL DEFAULT '', note VARCHAR(500) NOT NULL DEFAULT '', deleted BOOLEAN NOT NULL DEFAULT FALSE);
ALTER TABLE stock_documents ADD COLUMN carrier_cost_known BOOLEAN NOT NULL DEFAULT TRUE;
ALTER TABLE vehicle_shipments ADD COLUMN carrier_cost_known BOOLEAN NOT NULL DEFAULT TRUE;
